mapper.select:
SELECT r.id, k.id AS knowledgeId, k.title FROM knowledge_relation r
INNER JOIN knowledge_item k ON k.id = CASE WHEN r.source_knowledge_id=#{id}
    THEN r.target_knowledge_id ELSE r.source_knowledge_id END
WHERE r.source_knowledge_id=#{id} OR r.target_knowledge_id=#{id}
ORDER BY r.created_at DESC, r.id DESC LIMIT #{pageSize} OFFSET #{offset}
